package net.civeira.phylax.features.document.themeversion.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LocaleVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property locale of theme version ")
  void test_locale_v_o_builder() {
    Assertions.assertFalse(LocaleVO.nullValue().getLocale().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LocaleVO.tryFrom(null).getLocale().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LocaleVO.from("one").getLocale().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LocaleVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LocaleVO.from("one").toString());
  }
}
